import{Z as s,e as t,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Dynamic Option Sources in Practice","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fields/dynamic-option-sources-in-practice.md","filePath":"guides/fields/dynamic-option-sources-in-practice.md","lastUpdated":1782532814000}'),n={name:"guides/fields/dynamic-option-sources-in-practice.md"};function r(o,e,l,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="dynamic-option-sources-in-practice" tabindex="-1">Dynamic Option Sources in Practice <a class="header-anchor" href="#dynamic-option-sources-in-practice" aria-label="Permalink to &quot;Dynamic Option Sources in Practice&quot;">​</a></h1><p>Dropdown, Radio, and Checkboxes fields can pull their options from several source types — not just a manually maintained table. This walkthrough shows when to use each option source and how they behave at render and submit time.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/fields/option-sources">Option Sources reference</a></li></ul><h2 id="the-five-source-types" tabindex="-1">The Five Source Types <a class="header-anchor" href="#the-five-source-types" aria-label="Permalink to &quot;The Five Source Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Best for</th></tr></thead><tbody><tr><td><strong>Static</strong></td><td>Short, fixed lists you curate in the form builder</td></tr><tr><td><strong>Predefined</strong></td><td>Built-in datasets (countries, states, currencies, languages)</td></tr><tr><td><strong>Integration</strong></td><td>Remote picklists from connected CRM or marketing tools</td></tr><tr><td><strong>Template</strong></td><td>Per-request lists built in Twig</td></tr><tr><td><strong>Custom Provider</strong></td><td>Server-resolved Craft data via a registered provider</td></tr></tbody></table><p>Authors choose the type under the field&#39;s <strong>Options</strong> setting.</p><h2 id="static-—-full-control-in-the-builder" tabindex="-1">Static — Full Control in the Builder <a class="header-anchor" href="#static-—-full-control-in-the-builder" aria-label="Permalink to &quot;Static — Full Control in the Builder&quot;">​</a></h2><p>Use <strong>Static</strong> when the list is short, changes rarely, and authors should manage it directly.</p><ul><li>Edit rows in the options table.</li><li>Use <strong>Bulk add options</strong> to paste many rows at once.</li><li>Set per-row availability (visible, hidden, disabled).</li><li>Submitted values store the value only — no label snapshot.</li></ul><p>Static is the default when the field only defines an <code>options</code> table in the builder.</p><h2 id="predefined-—-ship-common-datasets-without-maintenance" tabindex="-1">Predefined — Ship Common Datasets Without Maintenance <a class="header-anchor" href="#predefined-—-ship-common-datasets-without-maintenance" aria-label="Permalink to &quot;Predefined — Ship Common Datasets Without Maintenance&quot;">​</a></h2><p>Use <strong>Predefined</strong> when Formie already ships the list:</p><ol><li>Set <strong>Options</strong> to <strong>Predefined</strong>.</li><li>Choose the <strong>List</strong> (countries, states/provinces, currencies, languages).</li><li>Pick which source fields map to <strong>Option Label</strong> and <strong>Option Value</strong>.</li></ol><p>Formie resolves the list when the form renders. The <strong>Preview</strong> panel shows a sample of rows.</p><p>You can copy a predefined subset into a static table with <strong>Bulk add options</strong> while the field is still <strong>Static</strong>, then curate manually.</p><p>At submit time, Formie validates against the resolved list and stores <strong>value and label</strong> so notifications stay accurate if the predefined list changes later.</p><h2 id="integration-—-follow-connected-provider-data" tabindex="-1">Integration — Follow Connected Provider Data <a class="header-anchor" href="#integration-—-follow-connected-provider-data" aria-label="Permalink to &quot;Integration — Follow Connected Provider Data&quot;">​</a></h2><p>Use <strong>Integration</strong> when options should track a connected service:</p><ol><li>Set <strong>Options</strong> to <strong>Integration</strong>.</li><li>Choose the <strong>Integration</strong> instance.</li><li>Choose the <strong>Source</strong> (for example HubSpot form fields vs CRM properties).</li><li>Complete any additional settings for that source.</li></ol><p>Supported integrations include Mailchimp interest groups, HubSpot form fields and CRM properties, Salesforce picklists, Zoho picklists, and Microsoft Dynamics 365 picklists.</p><p>Before a source returns options, refresh provider data in the form&#39;s <strong>Integrations</strong> tab. In field settings, use <strong>Refresh Preview</strong> to re-resolve from cache, or <strong>Refresh Integration Data</strong> to fetch fresh remote data.</p><p><strong>Convert to Static Options</strong> freezes the current remote list into the static table and drops the provider link — useful when you want to stop depending on the remote source.</p><h2 id="template-—-developer-controlled-per-render" tabindex="-1">Template — Developer-Controlled per Render <a class="header-anchor" href="#template-—-developer-controlled-per-render" aria-label="Permalink to &quot;Template — Developer-Controlled per Render&quot;">​</a></h2><p>Use <strong>Template</strong> when the list depends on the current page, entry, user, or site — and a developer controls the Twig template:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> craft.formie.forms.handle(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).one() %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> departments </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> craft.entries()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .section(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;departments&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .orderBy(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;title&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .all() %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form.setFieldSettings(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;department&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    options: departments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">map(entry =&gt; {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        label: entry.title,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        value: entry.slug,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        default: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(form) }}</span></span></code></pre></div><p>For nested fields, include the parent handle: <code>contactDetails.department</code>. See <a href="/templates/overriding-settings">Overriding Settings</a>.</p><h3 id="template-caveats" tabindex="-1">Template Caveats <a class="header-anchor" href="#template-caveats" aria-label="Permalink to &quot;Template Caveats&quot;">​</a></h3><ul><li><strong>No strict validation</strong> — Formie does not enforce an <code>in</code> range against a stored list. Your template is responsible for sensible choices.</li><li><strong>No builder preview</strong> — the form builder cannot know what Twig will output.</li><li><strong>Cached pages</strong> — template overrides run when Twig renders the form. Statically cached HTML keeps options from the render that built the cache. See <a href="/frontend/cached-forms">Cached Forms</a>.</li><li><strong>Prefer Predefined or Integration</strong> when a stable provider exists — you get preview, refresh, and stricter validation.</li></ul><h2 id="custom-provider-—-local-craft-data-with-builder-ui" tabindex="-1">Custom Provider — Local Craft Data with Builder UI <a class="header-anchor" href="#custom-provider-—-local-craft-data-with-builder-ui" aria-label="Permalink to &quot;Custom Provider — Local Craft Data with Builder UI&quot;">​</a></h2><p>Use <strong>Custom Provider</strong> when options come from Craft elements or custom PHP logic and authors need configurable params in the builder:</p><ol><li>Register a provider class (see <a href="/guides/fields/creating-a-custom-option-source-provider">Creating a custom option source provider</a>).</li><li>Set <strong>Options</strong> to <strong>Custom Provider</strong>.</li><li>Choose the provider and complete its param fields.</li></ol><p>Formie resolves rows at render and submit time, with the same validation behaviour as Predefined and Integration sources.</p><h2 id="picking-craft-elements" tabindex="-1">Picking Craft Elements <a class="header-anchor" href="#picking-craft-elements" aria-label="Permalink to &quot;Picking Craft Elements&quot;">​</a></h2><p>When authors need users to pick <strong>entries, categories, users, or tags</strong> as relations — not flat option rows — use the dedicated element field types instead of option sources. Element fields return element IDs, which fits relations, GraphQL, and integration mapping better.</p><h2 id="choosing-a-source-—-decision-flow" tabindex="-1">Choosing a Source — Decision Flow <a class="header-anchor" href="#choosing-a-source-—-decision-flow" aria-label="Permalink to &quot;Choosing a Source — Decision Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Is the list the same for every render?</span></span>
<span class="line"><span>├─ Yes → Is it a built-in dataset Formie ships?</span></span>
<span class="line"><span>│         ├─ Yes → Predefined</span></span>
<span class="line"><span>│         └─ No → Is it from a connected integration?</span></span>
<span class="line"><span>│                   ├─ Yes → Integration</span></span>
<span class="line"><span>│                   └─ No → Static (or Custom Provider if PHP logic is needed)</span></span>
<span class="line"><span>└─ No → Does it depend on Twig context (entry, user, site)?</span></span>
<span class="line"><span>          ├─ Yes → Template (watch caching)</span></span>
<span class="line"><span>          └─ No → Custom Provider</span></span></code></pre></div><p>Keep option <strong>values</strong> stable once submissions, integrations, or reports depend on them. Changing a value invalidates older submissions during strict validation.</p>`,38)])])}const u=s(n,[["render",r]]);export{g as __pageData,u as default};
